"use strict";(globalThis.webpackChunkmindstack=globalThis.webpackChunkmindstack||[]).push([[97],{926(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"category","label":"Network","items":[{"type":"link","href":"/Mindstack/docs/networks/Introduction","label":"Introduction","docId":"networks/Introduction","unlisted":false},{"type":"link","href":"/Mindstack/docs/networks/Fundamentals","label":"Fundamentals","docId":"networks/Fundamentals","unlisted":false},{"type":"link","href":"/Mindstack/docs/networks/Switching&LANs","label":"Switching & VLANs","docId":"networks/Switching&LANs","unlisted":false},{"type":"link","href":"/Mindstack/docs/networks/Routing","label":"Routing","docId":"networks/Routing","unlisted":false},{"type":"link","href":"/Mindstack/docs/networks/IPServices","label":"IP Services","docId":"networks/IPServices","unlisted":false},{"type":"link","href":"/Mindstack/docs/networks/Security","label":"Security","docId":"networks/Security","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"intro":{"id":"intro","title":"Tutorial Intro","description":"Let\'s discover Docusaurus in less than 5 minutes."},"networks/Fundamentals":{"id":"networks/Fundamentals","title":"Network Fundamentals","description":"Networking is fundamentally about moving information between autonomous systems over shared infrastructure. To understand how this works in a structured way, we rely on layered models \u2014 most notably the OSI model and the TCP/IP model.","sidebar":"docsSidebar"},"networks/Introduction":{"id":"networks/Introduction","title":"Introduction to Networking","description":"A computer network is a system of interconnected devices\u2014such as computers, servers, routers, switches, and wireless access points\u2014that communicate to exchange information and share resources. Each device (or host) has a unique address, allowing data to be sent, routed, and received reliably. Networks range from small Local Area Networks (LANs) to global systems like the Internet, enabling applications such as web browsing, email, file sharing, and cloud computing. In modern IT environments, nearly every device relies on networking to access services and data.","sidebar":"docsSidebar"},"networks/IPServices":{"id":"networks/IPServices","title":"IP Services","description":"IP services are critical for enabling communication and resource access within and between networks. They provide addressing, translation, resolution, and synchronization, forming the foundation of functional network operations.","sidebar":"docsSidebar"},"networks/Routing":{"id":"networks/Routing","title":"Routing and IP Connectivity","description":"Routing is the process of forwarding packets between different networks based on logical addresses (IP addresses). Routers, operating at the Network layer, determine the best path for data to reach its destination, enabling inter-network communication.","sidebar":"docsSidebar"},"networks/Security":{"id":"networks/Security","title":"Network Security Fundamentals","description":"Network security ensures that data, devices, and infrastructure are protected from unauthorized access, misuse, and attacks. Security in networking involves access control, authentication, encryption, and monitoring, all designed to maintain confidentiality, integrity, and availability.","sidebar":"docsSidebar"},"networks/Switching&LANs":{"id":"networks/Switching&LANs","title":"Switching and VLANs","description":"Switches operate at the Data Link layer (Layer 2) to forward frames within a local area network (LAN). Their primary function is to deliver frames from a source MAC address to the correct destination MAC address, which is learned dynamically by observing incoming frames.","sidebar":"docsSidebar"}}}}')}}]);